  "criteria": [
    {
      "criterion": "材料与任务要求无歧义或明确保留未知",
      "verdict": "pass",
      "rationale": "s1 明确给出三项纳入条件及“没有失败但缺证据则待核验”的规则；s2 中 R 缺少同步记录，参考结论将其列为 unknown，符合保留未知状态要求。"
    },
    {
      "criterion": "参考事实、算术及来源对应正确",
      "verdict": "pass",
      "rationale": "P 缺测10%，满足“不超过10%”；Q 校准过期，明确失败；R 缺测2%但无同步记录。accepted=[P]、rejected=[Q]、unknown=[R] 均与 s1、s2 对应正确。"
    },
    {
      "criterion": "验收条件覆盖关键错误和全局约束",
      "verdict": "pass",
